<?php require_once __DIR__.'/../includes/functions.php'; require_admin(); $all=get_posts(); $slug=$_GET['slug']??'';$post=['title'=>'','slug'=>'','category'=>'Group Travel','date'=>date('Y-m-d'),'image'=>'','excerpt'=>'','content'=>''];foreach($all as $p){if($slug && $p['slug']===$slug){$post=$p;break;}}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$newSlug=slugify($_POST['slug']?:$title);$date=$_POST['date']?:date('Y-m-d');$image=trim($_POST['image']??'');$excerpt=trim($_POST['excerpt']??'');$content=trim($_POST['content']??'');$category=trim($_POST['category']??'Group Travel');if(!$title||!$excerpt||!$content){$error='Please complete the title, excerpt and article content.';}else{foreach($all as $existing){if($existing['slug']===$newSlug && $existing['slug']!==$slug){$newSlug.='-'.substr(uniqid(),-4);}}$record=['title'=>$title,'slug'=>$newSlug,'category'=>$category,'date'=>$date,'image'=>$image,'excerpt'=>$excerpt,'content'=>$content];$updated=false;foreach($all as $i=>$existing){if($slug && $existing['slug']===$slug){$all[$i]=$record;$updated=true;break;}}if(!$updated)$all[]=$record;save_posts($all);header('Location: index.php?saved=1');exit;}$post=array_merge($post,$_POST);}$pageTitle=$slug?'Edit article':'Create article';include __DIR__.'/../includes/header.php'; ?>
<section class="admin-wrap"><form class="editor-panel" method="post"><a class="back-link" href="index.php">← Back to dashboard</a><span class="eyebrow dark">BLOG EDITOR</span><h1><?= $slug?'Edit your':'Create a new' ?> <em>article.</em></h1><?php if($error): ?><p class="error"><?= e($error) ?></p><?php endif; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Article title<input name="title" required value="<?= e($post['title']) ?>" placeholder="How to plan a group flight"></label><div class="form-row"><label>URL slug (optional)<input name="slug" value="<?= e($post['slug']) ?>" placeholder="auto-generated-from-title"></label><label>Category<input name="category" value="<?= e($post['category']) ?>"></label></div><div class="form-row"><label>Publish date<input type="date" name="date" value="<?= e($post['date']) ?>"></label><label>Cover image URL<input name="image" value="<?= e($post['image']) ?>" placeholder="https://example.com/image.jpg"></label></div><label>Short excerpt<textarea name="excerpt" rows="3" required maxlength="300" placeholder="A short introduction shown on the blog page..."><?= e($post['excerpt']) ?></textarea></label><label>Article content<textarea name="content" rows="15" required placeholder="Write your article here. Separate paragraphs with a blank line."><?= e($post['content']) ?></textarea></label><div class="editor-buttons"><button class="btn btn-dark" type="submit">Save article →</button><a class="under-link" href="index.php">Cancel</a></div><small>Use plain text for article content. Add a public image URL for the cover image. The post is saved in data/posts.json.</small></form></section><?php include __DIR__.'/../includes/footer.php'; ?>